data.command:
/bin/zsh -lc "/Users/omar/.codex/skills/openpencil/scripts/openpencil-cli.sh board build --fresh-context --runtime-instance-id 'local-authority:local-authority-f06b17af-2b12-4b51-8e75-49506e084910' --workspace-id 'workspace-44c2b737-ada8-4e45-b8d9-1d30aadf4fdc' --document-id 'document-1b633407-6552-4f35-a64b-7ac3899a306d' --content-document-id 'document-1b633407-6552-4f35-a64b-7ac3899a306d' --page-id '0:2085' --request-id 'deep-space-greenhouse-control-v1' --intent 'Build a compact deep-space greenhouse control panel with durable light, water, growth mode, live readiness, reset semantics, and concise connected native operating context.' --plan-file - --json <<'GREENHOUSE_PLAN'
{
  \"contract\": \"board-build-plan/v1\",
  \"artifacts\": [
    {
      \"alias\": \"greenhouse_panel\",
      \"recipe\": {
        \"kind\": \"code_object\",
        \"operation\": \"create\",
        \"source_format\": \"tsx\",
        \"object_key\": \"deep-space-greenhouse-control-v1\",
        \"name\": \"Deep-Space Greenhouse Control\",
        \"width\": 680,
        \"height\": 520,
        \"initial_state\": {
          \"light\": 76,
          \"water\": 62,
          \"mode\": \"Vegetative\"
        },
        \"placement\": {
          \"target\": {
            \"kind\": \"auto\"
          }
        },
        \"source\": \"type GrowthMode = 'Seedling' | 'Vegetative' | 'Fruiting';\\ntype GreenhouseState = { light: number; water: number; mode: GrowthMode };\\ntype ControlProps = { state: GreenhouseState; setState: (updater: (current: GreenhouseState) => GreenhouseState) => void };\\n\\nconst defaults: GreenhouseState = { light: 76, water: 62, mode: 'Vegetative' };\\nconst modeBands: Record<GrowthMode, { light: [number, number]; water: [number, number] }> = {\\n  Seedling: { light: [45, 60], water: [65, 80] },\\n  Vegetative: { light: [70, 82], water: [55, 68] },\\n  Fruiting: { light: [78, 90], water: [62, 76] }\\n};\\n\\nexport default function DeepSpaceGreenhouseControl({ state, setState }: ControlProps) {\\n  const light = state.light ?? defaults.light;\\n  const water = state.water ?? defaults.water;\\n  const mode = state.mode ?? defaults.mode;\\n  const band = modeBands[mode];\\n  const alert = light >= 93 || light <= 30 || water <= 30 || water >= 92;\\n  const lightReady = light >= band.light[0] && light <= band.light[1];\\n  const waterReady = water >= band.water[0] && water <= band.water[1];\\n  const ready = "'!alert && lightReady && waterReady;'"\\n  const status = alert ? 'ALERT' : ready ? 'READY' : 'ADJUST';\\n  const statusColor = alert ? '#ff6b78' : ready ? '#62e6a8' : '#ffc66d';\\n  const update = (key: 'light' | 'water', value: number) => setState(current => ({ ...current, [key]: value }));\\n  const setMode = (nextMode: GrowthMode) => setState(current => ({ ...current, mode: nextMode }));\\n  const reset = () => setState(() => ({ ...defaults }));\\n\\n  return (\\n    <div style={{ boxSizing: 'border-box', width: '100%', height: '100%', padding: 24, color: '#e9f5ff', background: 'radial-gradient(circle at 84% 12%, #17395a 0, #0b1c31 34%, #07111f 74%)', fontFamily: 'Inter, ui-sans-serif, system-ui', border: '1px solid #244a68', borderRadius: 24, display: 'flex', flexDirection: 'column', gap: 18, overflow: 'hidden' }}>\\n      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 20 }}>\\n        <div>\\n          <div style={{ color: '#62e6a8', fontSize: 11, fontWeight: 800, letterSpacing: 2 }}>ORBITAL AGRONOMY / BAY 03</div>\\n          <h1 style={{ margin: '7px 0 0', fontSize: 26, lineHeight: 1.1 }}>Deep-Space Greenhouse</h1>\\n          <div style={{ marginTop: 7, color: '#8da9c4', fontSize: 13 }}>Crop loop control · durable board state</div>\\n        </div>\\n        <div style={{ minWidth: 150, padding: '11px 14px', borderRadius: 14, border: "'`1px solid ${statusColor}55`, background: `${statusColor}14` }}>'"\\n          <div style={{ color: '#8da9c4', fontSize: 10, fontWeight: 800, letterSpacing: 1.6 }}>READINESS</div>\\n          <div style={{ color: statusColor, fontSize: 23, fontWeight: 900, marginTop: 3 }}>{status}</div>\\n        </div>\\n      </header>\\n\\n      <section style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14 }}>\\n        {[\\n          { label: 'LIGHT INTENSITY', key: 'light' as const, value: light, accent: '#78b7ff' },\\n          { label: 'WATER ALLOCATION', key: 'water' as const, value: water, accent: '#5fe0d0' }\\n        ].map(control => (\\n          <div key={control.key} style={{ padding: 16, borderRadius: 16, background: '#0c2238cc', border: '1px solid #1e405c' }}>\\n            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>\\n              <span style={{ color: '#9db5ca', fontSize: 11, fontWeight: 800, letterSpacing: 1.2 }}>{control.label}</span>\\n              <strong style={{ color: control.accent, fontSize: 24 }}>{control.value}%</strong>\\n            </div>\\n            <input aria-label={control.label} type=\\\"range\\\" min=\\\"0\\\" max=\\\"100\\\" value={control.value} onChange={event => update(control.key, Number(event.currentTarget.value))} style={{ width: '100%', margin: '16px 0 8px', accentColor: control.accent }} />\\n            <div style={{ height: 5, borderRadius: 99, background: '#18334b', overflow: 'hidden' }}>\\n              <div style={{ width: "'`${control.value}%`, height: '"'100%', background: control.accent, borderRadius: 99 }} />\\n            </div>\\n          </div>\\n        ))}\\n      </section>\\n\\n      <section style={{ padding: 16, borderRadius: 16, background: '#0c2238cc', border: '1px solid #1e405c' }}>\\n        <div style={{ color: '#9db5ca', fontSize: 11, fontWeight: 800, letterSpacing: 1.2, marginBottom: 11 }}>GROWTH MODE</div>\\n        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 8 }}>\\n          {(['Seedling', 'Vegetative', 'Fruiting'] as GrowthMode[]).map(option => (\\n            <button key={option} onClick={() => setMode(option)} style={{ cursor: 'pointer', border: option === mode ? '1px solid #62e6a8' : '1px solid #294b65', background: option === mode ? '#62e6a822' : '#10283e', color: option === mode ? '#dfffee' : '#a7bfd1', padding: '10px 8px', borderRadius: 10, fontWeight: 800 }}>{option}</button>\\n          ))}\\n        </div>\\n      </section>\\n\\n      <section style={{ display: 'grid', gridTemplateColumns: '1fr auto', gap: 14, alignItems: 'stretch' }}>\\n        <div style={{ padding: '13px 15px', borderRadius: 14, background: '#091a2c', border: '1px solid #1a3851' }}>\\n          <div style={{ color: '#8da9c4', fontSize: 11, fontWeight: 800, letterSpacing: 1.1 }}>LIVE SUMMARY</div>\\n          <div style={{ marginTop: 6, fontSize: 14, lineHeight: 1.45 }}>\\n            {alert ? 'Boundary exceeded. Stabilize the crop loop now.' : ready ? "'`${mode} targets are balanced. Bay 03 is ready.` : `Tune ${!lightReady && !waterReady ? '"'light and water' : "'!lightReady ? '"'light' : 'water'} into the "'${mode.toLowerCase()} band.`}'"\\n          </div>\\n          <div style={{ marginTop: 7, color: '#7f9ab2', fontSize: 12 }}>Target · light {band.light[0]}–{band.light[1]}% · water {band.water[0]}–{band.water[1]}%</div>\\n        </div>\\n        <button onClick={reset} style={{ cursor: 'pointer', minWidth: 112, border: '1px solid #385a72', background: '#122b42', color: '#e7f3fb', borderRadius: 14, fontWeight: 850, padding: '0 20px' }}>Reset</button>\\n      </section>\\n    </div>\\n  );\\n}\\n\"
      }
    },
    {
      \"alias\": \"operating_target\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Operating Target\",
        \"body\": \"Match the active growth-mode bands shown in the panel. Vegetative nominal: light 70–82%, water 55–68%. READY means both resources are inside band.\"
      }
    },
    {
      \"alias\": \"alert_boundary\",
      \"recipe\": {
        \"kind\": \"native_card\",
        \"title\": \"Alert Boundary\",
        \"body\": \"Immediate ALERT at light ≤30% or ≥93%, or water ≤30% or ≥92%. Stabilize the crop loop before increasing growth mode.\"
      }
    }
  ],
  \"connections\": [
    {
      \"kind\": \"visual\",
      \"label\": \"guides settings\",
      \"source\": { \"alias\": \"operating_target\" },
      \"target\": { \"alias\": \"greenhouse_panel\" }
    },
    {
      \"kind\": \"visual\",
      \"label\": \"defines alert\",
      \"source\": { \"alias\": \"alert_boundary\" },
      \"target\": { \"alias\": \"greenhouse_panel\" }
    }
  ],
  \"layout\": {
    \"kind\": \"grid\",
    \"anchor\": { \"alias\": \"greenhouse_panel\" },
    \"members\": [\"operating_target\", \"alert_boundary\"],
    \"columns\": 2,
    \"column_gap\": 28,
    \"row_gap\": 28,
    \"align\": \"start\",
    \"placement\": {
      \"clearance\": 48,
      \"preferred_directions\": [\"below\"]
    }
  }
}
GREENHOUSE_PLAN"

